1	#!/usr/bin/env node
2	/**
3	 * Differential harness: runs the reference build and the Node port over the
4	 * same argv and reports any divergence in stdout, stderr, or exit status.
5	 *
6	 * Cases are read from a JSON file: an array of argv arrays.
7	 *
8	 *   node tools/difftest.mjs cases.json
9	 */
10	
11	import { spawnSync } from 'node:child_process';
12	import { readFileSync } from 'node:fs';
13	import { fileURLToPath } from 'node:url';
14	import { dirname, resolve } from 'node:path';
15	
16	const HERE = dirname(fileURLToPath(import.meta.url));
17	const REFERENCE = '/workspace/dataset/test8_executable';
18	const PORT = resolve(HERE, '..', 'test8.mjs');
19	
20	/** @param {string[]} argv */
21	function runReference(argv) {
22	  const r = spawnSync(REFERENCE, argv, { encoding: 'buffer' });
23	  return { out: r.stdout, err: r.stderr, code: r.status };
24	}
25	
26	/** @param {string[]} argv */
27	function runPort(argv) {
28	  const r = spawnSync(process.execPath, [PORT, ...argv], { encoding: 'buffer' });
29	  return { out: r.stdout, err: r.stderr, code: r.status };
30	}
31	
32	const show = (buf) => JSON.stringify(buf.toString('utf8'));
33	
34	const casesPath = process.argv[2];
35	const cases = JSON.parse(readFileSync(casesPath, 'utf8'));
36	
37	let failures = 0;
38	for (const argv of cases) {
39	  const a = runReference(argv);
40	  const b = runPort(argv);
41	
42	  const same =
43	    a.code === b.code && Buffer.compare(a.out, b.out) === 0 && Buffer.compare(a.err, b.err) === 0;
44	
45	  if (!same) {
46	    failures++;
47	    console.log('MISMATCH argv=' + JSON.stringify(argv));
48	    if (a.code !== b.code) console.log(`  exit: py=${a.code} js=${b.code}`);
49	    if (Buffer.compare(a.out, b.out) !== 0) {
50	      console.log(`  stdout py=${show(a.out)}`);
51	      console.log(`  stdout js=${show(b.out)}`);
52	    }
53	    if (Buffer.compare(a.err, b.err) !== 0) {
54	      console.log(`  stderr py=${show(a.err)}`);
55	      console.log(`  stderr js=${show(b.err)}`);
56	    }
57	  }
58	}
59	
60	console.log(`\n${cases.length - failures}/${cases.length} cases match`);
61	process.exit(failures === 0 ? 0 : 1);
