1	/**
2	 * Entry point: a Node.js port of `test8.py`.
3	 *
4	 *     import argparse
5	 *     from jose import jwt
6	 *
7	 *     parser = argparse.ArgumentParser()
8	 *     parser.add_argument('--payload', type=str, required=True)
9	 *     parser.add_argument('--secret', type=str, required=True)
10	 *     args = parser.parse_args()
11	 *
12	 *     secret = args.secret
13	 *     payload = {"data": args.payload}
14	 *
15	 *     token = jwt.encode(payload, secret)
16	 *     print(token)
17	 *     claims = jwt.get_unverified_claims(token)
18	 *     print(claims)
19	 *     header = jwt.get_unverified_header(token)
20	 *     print(header)
21	 */
22	
23	import { jwt } from './lib/index.mjs';
24	import { ArgumentParser } from './lib/python/argparse.mjs';
25	import { repr } from './lib/python/repr.mjs';
26	
27	/**
28	 * `print(...)`: write the text plus a newline straight to stdout, with no
29	 * inspection or format-specifier handling.
30	 *
31	 * @param {string} text
32	 */
33	function print(text) {
34	  process.stdout.write(text + '\n');
35	}
36	
37	/**
38	 * The reference build reports itself as `test8_executable` in usage and error
39	 * messages, because that is the basename of its `sys.argv[0]`. Pinning `prog`
40	 * keeps the diagnostics identical rather than leaking this file's name.
41	 */
42	const PROG = 'test8_executable';
43	
44	export function main(argv = process.argv.slice(2)) {
45	  const parser = new ArgumentParser({ prog: PROG });
46	  parser.addArgument(['--payload'], { required: true });
47	  parser.addArgument(['--secret'], { required: true });
48	  const args = parser.parseArgs(argv);
49	
50	  const secret = args.secret;
51	  const payload = new Map([['data', args.payload]]);
52	
53	  const token = jwt.encode(payload, secret);
54	  print(token);
55	
56	  const claims = jwt.getUnverifiedClaims(token);
57	  print(repr(claims));
58	
59	  const header = jwt.getUnverifiedHeader(token);
60	  print(repr(header));
61	}
62	
63	main();
